/* Lunar Landing Site Navigator: one page. Earth and the Moon in 3D, the landing site on real terrain, a lander flown
   from Earth to touchdown, and a landing check for any site and time. */
import React, { useState } from "react";
import { Mission } from "./Mission";

export class ErrorBoundary extends React.Component<{ children: React.ReactNode }, { err: boolean }> {
  state = { err: false };
  static getDerivedStateFromError() {
    return { err: true };
  }
  render() {
    if (!this.state.err) return this.props.children;
    return (
      <div className="crash">
        <h1>Something went wrong</h1>
        <p>Reload the page to try again.</p>
        <button className="btn" onClick={() => location.reload()}>
          Reload
        </button>
      </div>
    );
  }
}

export default function App() {
  const [eng, setEng] = useState(false);
  return (
    <div className="app">
      <header className="top">
        <div className="brand">
          <div className="brand-mark" aria-hidden="true" />
          <div>
            <h1>LunaPoint</h1>
            <p>Pick a site, check it, and fly a lander there</p>
          </div>
        </div>
        <button className="eng-toggle" role="switch" aria-checked={eng} onClick={() => setEng((v) => !v)} title="Detailed GO / NO-GO data for the chosen spot and time">
          <span className="sw" aria-hidden="true" />
          Go / No-Go
        </button>
      </header>
      <Mission engineer={eng} onEngineer={setEng} />
    </div>
  );
}
